      "rationale": "The cited spans establish documentary gaps, unobserved offline preparation, treatment of follow-up uncertainty, and the bounded cohort."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C046.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
